.gmw-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.gmw-root,.gmw-root *,.gmw-root *::before,.gmw-root *::after{box-sizing:border-box}
.gmw-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.gmw-root img{display:block;border:0;max-width:none}
.gmw-root > [data-node-id]{will-change:transform}
.gmw-root [hidden]{display:none!important}
.gmw-root [data-sh-theme="light"]{display:none!important}
.gmw-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.gmw-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.gmw-root .nS1_3096_3452{position:absolute;height:32px;left:0;top:0;width:326px}
.gmw-root .nS1_I3096_3452_52_478{position:absolute;inset:-1.25% 0.14% 0.43% 0.63%}
.gmw-root .x100020{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.gmw-root .nS1_I3096_3452_52_479{position:absolute;background-color:var(--wa-point, #88d0fe);inset:38.51% 98.39% 27.69% 0.63%}
.gmw-root .nS1_I3096_3452_52_479::after{content:"";position:absolute;inset:-0px;border:2px solid var(--wa-line, #081332);border-radius:inherit;pointer-events:none}
.gmw-root .nS1_I3096_3452_52_480{word-break:break-word;position:absolute;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:440;inset:27.28% 46.52% 28.97% 6.53%;line-height:14px;font-style:normal;font-size:14px;color:var(--wa-text, #fff);width:153.044px;white-space:nowrap}
.gmw-root [data-name="Tab/GAS#1 (Active)"] + [data-name="Tab/GAS#1 (Active)"]{display:none!important}
.gmw-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.gmw-root[data-theme="light"] [data-name="Badge/Critical"] p,.gmw-root[data-theme="light"] [data-name^="status-critical"] p,.gmw-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.gmw-root[data-theme="light"] [data-name="Badge/Major"] p,.gmw-root[data-theme="light"] [data-name^="status-major"] p,.gmw-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #ad4d00)!important;font-weight:600;white-space:nowrap}
.gmw-root[data-theme="light"] [data-name="Badge/Minor"] p,.gmw-root[data-theme="light"] [data-name^="status-minor"] p,.gmw-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #856000)!important;font-weight:600;white-space:nowrap}
.gmw-root[data-theme="light"] [data-name="Badge/Warning"] p,.gmw-root[data-theme="light"] [data-name^="status-warning"] p,.gmw-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.gmw-root[data-theme="light"] [data-name="Badge/Normal"] p,.gmw-root[data-theme="light"] [data-name^="status-normal"] p,.gmw-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.gmw-root[data-theme="light"] [data-name^="Button/"]:not([data-name="Button/Close"]):not([data-name="Button/Ack"]) p{color:var(--wa-text, #fff)!important}
.gmw-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
